def solve(g):
    cc=comps(g); cnt={kk:len(v) for kk,v in cc.items()}
    bigk=max(cnt,key=cnt.get); smallk=min(cnt,key=cnt.get)
    big=list(comps(g)[bigk]); small=set(comps(g)[smallk])
    H,W=len(g),len(g[0])
    br_=min(r for r,c in big); bc_=min(c for r,c in big)
    h=max(r-br_ for r,c in big)+1; w=max(c-bc_ for r,c in big)+1
    shp=[(r-br_,c-bc_) for r,c in big]
    # decide side from small centroid relative to big centroid
    sb=(sum(r for r,c in small)/len(small), sum(c for r,c in small)/len(small))
    bb=(br_+(h-1)/2, bc_+(w-1)/2)
    below = sb[0]>bb[0]; right = sb[1]>bb[1]
    if below and not right:   # flipv, flush below
        shp=[(h-1-a,b) for a,b in shp]; dr=h
        sc=bc_
    elif right and not below: # fh, flush right
        shp=[(a,w-1-b) for a,b in shp]; dr=br_
        sc=bc_+w
    else:                     # both or neither -> default: flipv below
        shp=[(h-1-a,b) for a,b in shp]; dr=h; sc=bc_
    out=[row[:] for row in g]
    cov=set()
    for a,b in shp:
        rr=br_+dr+a; c2=sc+b
        if 0<=rr<H and 0<=c2<W:
            out[rr][c2]=bigk; cov.add((rr,c2))
    for r,c in small:
        if (r,c) not in cov: out[r][c]=0
    return out
