    pts=[(r,c) for r,c in cells]
    outs={}
    for name,f in [('id',lambda p:p),('rv',lambda p:(-p[0],p[1])),('rh',lambda p:(p[0],-p[1])),('r180',lambda p:(-p[0],-p[1]))]:
