    base=[(r-br_,c-bc_) for r,c in bg]
    ibg={(r,c) for r in range(H) for c in range(W) if i[r][c]==bcol}
    trns={'id':base,'fh':[(a,w-1-b) for a,b in base],'tv':[(-a,b) for a,b in base],'r180':[(-a,w-1-b) for a,b in base]}
    hits=[]
    for tn,T in trns.items():
        hh=max(a for a,b in T)+1; ww=max(b for a,b in T)+1
        for rr in range(-hh+1,H):
            for cc in range(-ww+1,W):
                S={(a+rr,b+cc) for a,b in T}
                if all(0<=p[0]<H and 0<=p[1]<W for p in S) and not(S & ibg):
                    cr=sum(a+rr for a,b in T)/len(T); cn=sum(b+cc for a,b in T)/len(T)
                    mr=sum(r for r,c in sg)/len(sg); mc=sum(c for r,c in sg)/len(sg)
                    dist=abs(cr-mr)+abs(cn-mc)
                    gaps=min(abs(r-r0)+abs(c-c0) for r,c in S for r0,c0 in bg)
                    hits.append((dist,tn,(rr,cc)))
    return sorted(hits)[0],br_,bc_
